import assert from "node:assert/strict";
import {transform} from "lightningcss";
const dir=import.meta.dir,tick=String.fromCharCode(96);
const css=await Bun.file(dir+"/separator.css").text();
const result=transform({filename:"house/separator.css",code:Buffer.from(css),sourceMap:true,minify:false});
const map=JSON.parse(result.map.toString());
const dataURL="data:application/json;base64,"+Buffer.from(JSON.stringify(map)).toString("base64");
const withMap=result.code.toString()+"\n/*# sourceURL=acme-styles://separator.css */\n/*# sourceMappingURL="+dataURL+" */";
const escape=s=>s.replaceAll("\\","\\\\").replaceAll(tick,"\\"+tick).replaceAll("$"+"{","\\$"+"{");
const entry='import {LitElement,html,css} from "lit";export const style=css'+tick+escape(withMap)+tick+';class MapProbe extends LitElement { static styles=style; render(){return html'+tick+'<div class="separator"></div>'+tick+';}}customElements.define("map-probe",MapProbe);';
await Bun.write(dir+"/map-browser.js",entry);
const build=await Bun.build({entrypoints:[dir+"/map-browser.js"],target:"browser",sourcemap:"external",minify:true,write:false});
assert.ok(build.success);
const js=await build.outputs.find(x=>x.kind==="entry-point").text();
const server=Bun.serve({port:0,fetch(req){return new URL(req.url).pathname==="/app.js"?new Response(js,{headers:{"Content-Type":"text/javascript"}}):new Response('<html><body><map-probe></map-probe><script type="module" src="/app.js"></script></body></html>',{headers:{"Content-Type":"text/html"}});}});
process.env.PLAYWRIGHT_BROWSERS_PATH="/var/folders/b6/2r9mrtsj70s3x013xbhxt2yr0000gn/T/acme-style-engines-fHTyxk/browsers";
const pw=await import("/var/folders/b6/2r9mrtsj70s3x013xbhxt2yr0000gn/T/acme-style-engines-fHTyxk/package/index.mjs");
const outcomes=[];
try {for(const engine of ["chromium","firefox","webkit"]){
 const browser=await pw[engine].launch(engine==="chromium"?{headless:true,executablePath:"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"}:{headless:true});
 try{
 const page=await browser.newPage();const errors=[];page.on("pageerror",e=>errors.push(e.message));
 const headers=[];let session;
 if(engine==="chromium"){session=await page.context().newCDPSession(page);session.on("CSS.styleSheetAdded",({header})=>headers.push(header));await session.send("DOM.enable");await session.send("CSS.enable");}
 await page.goto(server.url.href);await page.waitForFunction(()=>document.querySelector("map-probe")?.shadowRoot?.querySelector(".separator"));
 if(session)await session.send("DOM.getDocument",{depth:-1,pierce:true});
 const rendered=await page.evaluate(()=>getComputedStyle(document.querySelector("map-probe").shadowRoot.querySelector(".separator")).height);
 assert.equal(rendered,"1px");assert.deepEqual(errors,[]);
 let mapped;
 if(engine==="chromium"){
 const header=headers.find(h=>h.sourceURL==="acme-styles://separator.css");assert.ok(header);assert.equal(header.sourceMapURL,dataURL);
 const decoded=JSON.parse(Buffer.from(header.sourceMapURL.split(",")[1],"base64").toString());
 assert.deepEqual(decoded,map);assert.equal(decoded.sourcesContent[0],css);
 mapped={isConstructed:header.isConstructed,sourceURL:header.sourceURL,sourceMapRecognized:true,source:decoded.sources[0],originalContentExact:true,mappingsPresent:decoded.mappings.length>0};
 }
 outcomes.push({engine,version:browser.version(),rendered,errors,devtools:mapped??"CSS rendering tested; DevTools map UI not tested for this engine"});
 }finally{await browser.close();}
}}finally{server.stop(true);}
const evidence={bun:Bun.version,compiler:"lightningcss@1.33.0",path:"authored CSS -> compiler map -> generated Lit css template -> minified Bun bundle -> actual adopted stylesheet -> Chromium CSS domain recognizes original map",outcomes,limits:["The CSS debugger resolves the original CSS directly; this is not a claim that JS breakpoints inside CSS strings map meaningfully","Firefox/WebKit DevTools map interfaces not automated","Development map artifacts must be omitted from minimal production entry by build configuration; package check follows"],bundleBytes:Buffer.byteLength(js)};
await Bun.write(dir+"/map-delivery-results.json",JSON.stringify(evidence,null,2));console.log(JSON.stringify(evidence,null,2));

