import assert from "node:assert/strict";
import {generateKeyPairSync,verify,createHash,X509Certificate} from "node:crypto";
import {mkdtemp,writeFile,rm} from "node:fs/promises";
import {tmpdir} from "node:os";
const dir=await mkdtemp(tmpdir()+"/acme-release-crypto-");
const ca=generateKeyPairSync("ec",{namedCurve:"prime256v1",privateKeyEncoding:{type:"pkcs8",format:"pem"},publicKeyEncoding:{type:"spki",format:"pem"}});
await writeFile(dir+"/local-test-ca.pem",ca.privateKey,{mode:0o600});
const calls=[];let certificate,publicKey,metadata;
const jwt="local."+Buffer.from(JSON.stringify({sub:"repo:local/m00:ref:refs/heads/test",iss:"https://token.actions.githubusercontent.com",repository_visibility:"public"})).toString("base64url")+".test";
const server=Bun.serve({port:0,hostname:"127.0.0.1",fetch:async req=>{
 const path=new URL(req.url).pathname.replace(/\/+/g,"/");calls.push({method:req.method,path});
 if(path==="/oidc")return Response.json({value:jwt});
 if(path==="/api/v2/signingCert"){
 const body=await req.json();publicKey=body.publicKeyRequest.publicKey.content;
 assert.equal(body.credentials.oidcIdentityToken,jwt);
 assert.ok(verify("sha256",Buffer.from("repo:local/m00:ref:refs/heads/test"),publicKey,Buffer.from(body.publicKeyRequest.proofOfPossession,"base64")));
 await writeFile(dir+"/public.pem",publicKey);
 const p=Bun.spawn(["openssl","x509","-new","-force_pubkey",dir+"/public.pem","-subj","/CN=Local M00 test","-key",dir+"/local-test-ca.pem","-days","1","-out",dir+"/certificate.pem"],{stdout:"pipe",stderr:"pipe"});
 const stderr=await new Response(p.stderr).text();assert.equal(await p.exited,0,stderr);
 certificate=await Bun.file(dir+"/certificate.pem").text();
 return Response.json({signedCertificateEmbeddedSct:{chain:{certificates:[certificate]}}});
 }
 if(path==="/api/v1/log/entries"){
 const body=await req.json();
 const encoded=Buffer.from(JSON.stringify(body)).toString("base64");
 return Response.json({"local-test-entry":{body:encoded,integratedTime:Math.floor(Date.now()/1000),logID:"01".repeat(32),logIndex:1,verification:{signedEntryTimestamp:Buffer.from("LOCAL MOCK WITNESS ONLY").toString("base64")}}});
 }
 if(path==="/acme-m00-publish-probe"&&req.method==="PUT"){metadata=await req.json();return Response.json({ok:true},{status:201});}
 return new Response("unexpected route",{status:404});
}});
Object.assign(process.env,{CI:"true",GITHUB_ACTIONS:"true",GITHUB_REPOSITORY:"local/m00",GITHUB_WORKFLOW_REF:"local/m00/.github/workflows/test.yml@refs/heads/test",GITHUB_SERVER_URL:"https://github.com",GITHUB_EVENT_NAME:"workflow_dispatch",GITHUB_REPOSITORY_ID:"0",GITHUB_REPOSITORY_OWNER_ID:"0",GITHUB_REF:"refs/heads/test",GITHUB_SHA:"0".repeat(40),GITHUB_RUN_ID:"0",GITHUB_RUN_ATTEMPT:"1",RUNNER_ENVIRONMENT:"github-hosted",ACTIONS_ID_TOKEN_REQUEST_URL:server.url.href+"oidc",ACTIONS_ID_TOKEN_REQUEST_TOKEN:"LOCAL TEST TOKEN"});
try{
 const {default:publish}=await import(import.meta.dir+"/node_modules/npm/node_modules/libnpmpublish/lib/publish.js");
 const tarball=Buffer.from(await Bun.file(import.meta.dir+"/release-fixture/acme-m00-publish-probe-0.0.0.tgz").arrayBuffer());
 await publish({name:"acme-m00-publish-probe",version:"0.0.0"},tarball,{registry:server.url.href,access:"public",provenance:true,fulcioURL:server.url.href,rekorURL:server.url.href,identityToken:jwt,npmVersion:"12.0.2",retry:0,timeout:5000});
 const attachments=metadata._attachments;
 const bundle=JSON.parse(attachments["acme-m00-publish-probe-0.0.0.sigstore"].data);
 const envelope=bundle.dsseEnvelope,payload=Buffer.from(envelope.payload,"base64"),statement=JSON.parse(payload);
 const pae=Buffer.concat([Buffer.from("DSSEv1 "+Buffer.byteLength(envelope.payloadType)+" "+envelope.payloadType+" "+payload.length+" "),payload]);
 assert.ok(verify("sha256",pae,new X509Certificate(certificate).publicKey,Buffer.from(envelope.signatures[0].sig,"base64")));
 const tampered=Buffer.from(pae);tampered[tampered.length-1]^=1;
 assert.equal(verify("sha256",tampered,new X509Certificate(certificate).publicKey,Buffer.from(envelope.signatures[0].sig,"base64")),false);
 assert.equal(statement.subject[0].digest.sha512,createHash("sha512").update(tarball).digest("hex"));
 assert.equal(statement.predicate.buildDefinition.externalParameters.workflow.path,".github/workflows/test.yml");
 assert.equal(statement.predicate.runDetails.builder.id,"https://github.com/actions/runner/github-hosted");
 assert.equal(bundle.verificationMaterial.tlogEntries.length,1);
 assert.equal(Buffer.from(attachments["acme-m00-publish-probe-0.0.0.tgz"].data,"base64").equals(tarball),true);
 const output={bun:Bun.version,npm:"12.0.2",calls,assertions:{proofOfPossession:true,realEcdsaSignature:true,tamperedSignatureRejected:true,tarballDigestMatches:true,workflowClaimsMatch:true,provenanceAttachmentPresent:true,tarballAttachmentExact:true,localWitnessIncluded:true},limits:["Only loopback mock registry, local certificate issuer and local witness used","Real Sigstore trust-chain/witness verification and live npm/GitHub identity policy remain release-environment checks","OpenSSL only issues the mock fixture certificate; npm signing/packing runs under Bun","No public publication, real credential access or external signing request"],candidateCommand:"bun <pinned npm package>/bin/npm-cli.js publish <prepacked tarball> --access public --provenance --ignore-scripts"};
 await Bun.write(import.meta.dir+"/release-crypto-results.json",JSON.stringify(output,null,2));console.log(JSON.stringify(output,null,2));
}finally{server.stop(true);await rm(dir,{recursive:true,force:true});}

