import {transform} from "lightningcss";
import assert from "node:assert/strict";
const root="/Users/peterkloss/Dev/ACMElabs/design-system";
const files=[...new Bun.Glob("src/**/*.styles.ts").scanSync({cwd:root})];
const checks=[],errors=[];
for(const path of files){try{
 const mod=await import(root+"/"+path);
 const entries=Object.entries(mod).filter(([k,v])=>v&&typeof v.cssText==="string");
 assert.ok(entries.length,path+" must have CSS result");
 for(const [name,css]of entries){
 const input=process.argv.includes("--candidate")&&path==="src/components/command-menu/command-menu-input.styles.ts"?await Bun.file(import.meta.dir+"/command-menu-input-corrected.css").text():css.cssText;
 const out=transform({filename:path,code:Buffer.from(input),sourceMap:true,minify:true});
 checks.push({path,export:name,inputBytes:Buffer.byteLength(css.cssText),outputBytes:out.code.length,mapSources:JSON.parse(out.map.toString()).sources,warnings:out.warnings});
 }
}catch(e){errors.push({path,error:String(e)});}}
const house=await Bun.file(root+"/src/geist.css").text();
try{const out=transform({filename:"styles/house.css",code:Buffer.from(house),sourceMap:true,minify:true});checks.push({path:"src/geist.css",inputBytes:Buffer.byteLength(house),outputBytes:out.code.length,warnings:out.warnings});}catch(e){errors.push({path:"src/geist.css",error:String(e)});}
const result={compiler:"lightningcss@1.33.0",bun:Bun.version,files:files.length,compiledOutputs:checks.length,errors,checks,scope:"Syntax/map compilation of every existing styles module and house sheet, not visual equivalence of every component"};
await Bun.write(import.meta.dir+(process.argv.includes("--candidate")?"/corpus-candidate-results.json":"/corpus-results.json"),JSON.stringify(result,null,2));console.log(JSON.stringify({files:files.length,compiled:checks.length,errors,warnings:checks.flatMap(x=>x.warnings).length}));assert.equal(errors.length,0);

