  /* Geist chrome and syntax fixtures (same in both themes) */
  --mac-red: #fe5f57;
  --mac-amber: #febb2e;
  --mac-green: #26c941;
  --highlight: #fff500;
  --scrim-dark: rgba(0, 0, 0, 0.4);

  /* ---------- Semantic tokens, mapped onto the scales ---------- */
  --bg: var(--ds-background-100);
  --surface: var(--ds-background-100);
  --surface-2: var(--ds-background-200);
  --comp: var(--ds-gray-100);
  --comp-hover: var(--ds-gray-200);
  --comp-active: var(--ds-gray-300);
