  --contrast-strong: var(--ds-gray-1000);
  --contrast-strong-hover: var(--ds-gray-900);
  --text: var(--ds-gray-1000);
  --text-2: var(--ds-gray-900);
  --muted: var(--ds-gray-900);
  --faint: var(--ds-gray-900);
  --accent: var(--ds-blue-700);
  --accent-hover: var(--ds-blue-800);
  --accent-ink: var(--ds-blue-900);
  --accent-weak: var(--ds-blue-100);
  --accent-border: var(--ds-blue-400);
  --success: var(--ds-green-700);
  --success-ink: var(--ds-green-900);
  --success-weak: var(--ds-green-100);
  --success-border: var(--ds-green-400);
  --warn: var(--ds-red-700);
  --warn-hover: var(--ds-red-800);
  --warn-solid: var(--ds-red-800);
  --warn-solid-hover: var(--ds-red-900);
  --warn-ink: var(--ds-red-900);
  --warn-weak: var(--ds-red-100);
  --warn-border: var(--ds-red-400);
  --on-warn: #ffffff;
  --caution: var(--ds-amber-900);
  --caution-bg: var(--ds-amber-700);
  --caution-solid: var(--ds-amber-800);
  --caution-weak: var(--ds-amber-100);
  --caution-border: var(--ds-amber-400);
  --on-contrast: var(--ds-background-100);
  --switch-track: var(--ds-background-100);
  --switch-active: var(--ds-gray-100);
  --seg-track: var(--switch-track);
  --seg-active: var(--switch-active);
  --shadow: var(--ds-shadow-small);
  --shadow-lg: var(--ds-shadow-modal);
  --ring: 0 0 0 2px var(--bg), 0 0 0 4px var(--ds-focus-color);

  /* ---------- Type ---------- */
  --mono: "GoogleSansCode Nerd Font Mono", "GoogleSansCode Nerd Font", "Google Sans Code", ui-monospace, "SF Mono", "SFMono-Regular", Menlo, Consolas, monospace;
  --sans: "Google Sans Flex", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --t-3xs: 10px;
  --t-2xs: 11px;
  --t-xs: 12px;
  --t-sm: 13px;
  --t-md: 14px;
  --t-lg: 16px;
  --t-xl: 20px;
  --t-2xl: 24px;
  --t-3xl: 32px;

  /* ---------- Shape and space (Geist: radius 6, unit 4, gap 24, page 1200) ---------- */
