export class Interaction {
    constructor(host, options = {}) {
        this.host = host;
        this.options = options;
        this.cleanup = [];
        host.addController(this);
    }
    /** Binds to the styled element; call from firstUpdated or whenever the element changes. */
    attach(el) {
        if (this.el === el)
            return;
        this.detach();
        if (!el)
            return;
        this.el = el;
        const on = (type, fn, opts) => {
            el.addEventListener(type, fn, opts);
            this.cleanup.push(() => el.removeEventListener(type, fn, opts));
        };
        const disabled = () => this.options.disabled?.() ?? (el.disabled || el.getAttribute("aria-disabled") === "true");
        on("pointerenter", (e) => {
            if (e.pointerType !== "touch" && !disabled())
                el.setAttribute("data-hover", "true");
        });
        on("pointerleave", () => {
            el.removeAttribute("data-hover");
            el.removeAttribute("data-active");
        });
        on("pointerdown", (e) => {
            if (disabled() || e.button !== 0)
                return;
            el.setAttribute("data-active", "true");
            const up = () => {
                el.removeAttribute("data-active");
                window.removeEventListener("pointerup", up);
                window.removeEventListener("pointercancel", up);
            };
            window.addEventListener("pointerup", up);
            window.addEventListener("pointercancel", up);
        });
        on("keydown", (e) => {
            if ((e.key === " " || e.key === "Enter") && !disabled())
                el.setAttribute("data-active", "true");
        });
        on("keyup", () => el.removeAttribute("data-active"));
        // focusin/focusout bubble, so a wrapper (a label around a hidden input) sees its control's focus too.
        on("focusin", (e) => {
            const target = e.target;
            const own = !this.options.ownFocus || target === el;
            if (own && (this.options.anyFocus || target.matches(":focus-visible")))
                el.setAttribute("data-focus", "true");
            el.setAttribute("data-focus-within", "true");
        });
        on("focusout", () => {
            el.removeAttribute("data-focus");
            el.removeAttribute("data-focus-within");
            el.removeAttribute("data-active");
        });
    }
    detach() {
        for (const c of this.cleanup)
            c();
        this.cleanup = [];
        this.el = undefined;
    }
    hostDisconnected() {
        this.detach();
    }
}

