import {LitElement,html} from 'lit';
import {atomState} from '/Users/peterkloss/Dev/ACMElabs/design-system/src/shared/atom-state';
export type Responsive = string|number|readonly (string|number|null|undefined)[]|Readonly<Record<string,string|number>>|undefined;
const bands=['compact','medium','expanded','large','extraLarge'];
const interval=(key:string):string=>{
 const index=bands.indexOf(key);if(index>=0)return `${index}:5`;
 if(key.endsWith('Only')){const i=bands.indexOf(key.slice(0,-4));if(i>=0)return `${i}:${Math.min(i+1,5)}`;}
 if(key.endsWith('Down')){const i=bands.indexOf(key.slice(0,-4));if(i>0)return `0:${i}`;}
 const match=key.match(/^(compact|medium|expanded|large|extraLarge)To(Compact|Medium|Expanded|Large|ExtraLarge)$/);
 if(match){const lo=bands.indexOf(match[1]),hi=bands.indexOf(match[2][0].toLowerCase()+match[2].slice(1));if(hi>lo)return `${lo}:${hi}`;}
 throw new TypeError('Unknown responsive condition');
};
const leaf=(value:unknown):value is string|number=>typeof value==='string'||(typeof value==='number'&&Number.isFinite(value)&&value>=0);
export function validateResponsive(value:unknown):Responsive {
 if(value===undefined||leaf(value))return value as Responsive;
 if(Array.isArray(value)){if(value.length>5||value.some(v=>v!=null&&!leaf(v)))throw new TypeError('Invalid responsive array');return Object.freeze([...value]);}
 if(!value||Object.getPrototypeOf(value)!==Object.prototype)throw new TypeError('Invalid responsive object');
 const ranges=new Map<string,unknown>();for(const [key,v]of Object.entries(value)){const range=interval(key);if(!leaf(v))throw new TypeError('Invalid responsive leaf');if(ranges.has(range)&&ranges.get(range)!==v)throw new TypeError('Conflicting equivalent intervals');ranges.set(range,v);}
 return Object.freeze({...value}) as Responsive;
}
type State={value:string;values:readonly string[];padding:Responsive;gridTemplateColumns:Responsive;defaultValue:string};
export class TransactionProbe extends LitElement {
 static properties={value:{type:String,noAccessor:true},values:{noAccessor:true,converter:{fromAttribute:(value:string)=>JSON.parse(value)}}};
 @atomState() private state:State={value:'',values:Object.freeze([]),padding:undefined,gridTemplateColumns:undefined,defaultValue:''};
 static get observedAttributes(){return [...super.observedAttributes,'padding','grid-template-columns'];}
 /** @attribute value */ get value():string{return this.state.value;}
 set value(value:string){this.commit({value});}
 /** @attribute values */ get values():readonly string[]{return this.state.values;}
 set values(values:readonly string[]){this.commit({values});}
 /** @attribute padding */ get padding():Responsive{return this.state.padding;}
 set padding(padding:Responsive){this.commit({padding});}
 /** @attribute grid-template-columns */ get gridTemplateColumns():Responsive{return this.state.gridTemplateColumns;}
 set gridTemplateColumns(gridTemplateColumns:Responsive){this.commit({gridTemplateColumns});}
 get defaultValue():string{return this.state.defaultValue;}
 set defaultValue(defaultValue:string){this.commit({defaultValue});}
 commit(patch:Partial<State>){
  const next={...this.state};
  for(const [key,value]of Object.entries(patch)){
   if(key==='value'||key==='defaultValue'){if(typeof value!=='string')throw new TypeError('Expected string');next[key]=value;}
   else if(key==='values'){if(!Array.isArray(value)||value.some(v=>typeof v!=='string'))throw new TypeError('Expected string array');next.values=Object.freeze([...value]);}
   else if(key==='padding'||key==='gridTemplateColumns')next[key]=validateResponsive(value);
   else throw new TypeError('Unknown state input');
  }
  this.state=next;
 }
 reset(){this.commit({value:this.defaultValue,values:[]});}
 attributeChangedCallback(name:string,old:string|null,value:string|null){
  if(name!=='padding'&&name!=='grid-template-columns'){super.attributeChangedCallback(name,old,value);return;}
  const key=name==='padding'?'padding':'gridTemplateColumns';
  try{
   const current=value?.trim();
   if(!current){this.commit({[key]:undefined});return;}
   if(CSS.supports(name,current)){this.commit({[key]:current});return;}
   if(/^\d+(\.\d+)?$/.test(current)){this.commit({[key]:Number(current)});return;}
   this.commit({[key]:JSON.parse(current)});
  }catch{this.commit({[key]:undefined});this.dispatchEvent(new Event('probe-invalid-style'));}
 }
 render(){return html`<output>${this.value}|${this.values.join(',')}|${JSON.stringify(this.padding)}</output>`;}
}

