import {LitElement,html,css} from 'lit';
import {createAtom} from '@tanstack/lit-store';
import {NativeFirstRegistryHost} from '/tmp/acme-m00-scoped-registry-NSLMRE/compat-style.js';
export class RealHost extends LitElement {
 static properties={as:{type:String}};
 static styles=css`:host{display:block;min-width:0} :host([as=span]){display:inline} .root{display:inherit}`;
 constructor(){super();this.as='div';}
 render(){return this.as==='span'?html`<span class="root"><slot></slot></span>`:html`<div class="root"><slot></slot></div>`;}
}
export class FormControl extends LitElement {
 static formAssociated=true;
 static shadowRootOptions={mode:'open',delegatesFocus:true};
 static get observedAttributes(){return ['name','form','disabled'];}
 store=createAtom({value:'',disabled:false,label:'',description:''});
 internals=this.attachInternals();
 get value(){return this.store.get().value;}
 set value(value){this.store.set(s=>({...s,value:String(value)}));this.sync();}
 sync(){this.internals.setFormValue(this.value);this.requestUpdate();}
 connectedCallback(){super.connectedCallback();this.sync();}
 attributeChangedCallback(){this.sync();}
 formAssociatedCallback(){this.sync();}
 formDisabledCallback(disabled){this.store.set(s=>({...s,disabled}));this.requestUpdate();}
 focus(options){this.shadowRoot?.querySelector('input')?.focus(options);}
 setFieldText(label,description){this.store.set(s=>({...s,label,description}));this.requestUpdate();}
 render(){const s=this.store.get();return html`<span id="owned-label" hidden>${s.label}</span><span id="owned-description" hidden>${s.description}</span><input aria-labelledby="owned-label" aria-describedby="owned-description" .value=${s.value} ?disabled=${s.disabled} @input=${e=>{this.value=e.target.value}}>`;}
}
export class FieldHost extends LitElement {
 static styles=css`:host{display:block}`;
 render(){return html`<slot></slot>`;}
 bind(){const control=this.querySelector('sem-control'),label=this.querySelector('[data-label]'),help=this.querySelector('[data-help]');if(!control||!label)return;const update=()=>control.setFieldText(label.textContent,help?.textContent??'');update();this.observer?.disconnect();this.observer=new MutationObserver(update);this.observer.observe(this,{subtree:true,characterData:true,childList:true});this.onClick=()=>control.focus();label.addEventListener('click',this.onClick);this.label=label;}
 connectedCallback(){super.connectedCallback();queueMicrotask(()=>this.bind());}
 disconnectedCallback(){super.disconnectedCallback();this.observer?.disconnect();this.label?.removeEventListener('click',this.onClick);}
}
export class ScopedFormHost extends NativeFirstRegistryHost(LitElement) {
 static elementDefinitions={'sem-control':class extends FormControl{},'sem-field':class extends FieldHost{}};
 render(){return html`<form id="owner"><sem-field><label data-label>Scoped email</label><sem-control name="email"></sem-control><span data-help>Required for receipts</span></sem-field></form>`;}
}
customElements.define('sem-box',RealHost);customElements.define('sem-control',FormControl);customElements.define('sem-field',FieldHost);customElements.define('sem-scoped-form',ScopedFormHost);
